<?php require __DIR__.'/common.php';requireRole('admin');require __DIR__.'/event_catalogue.php';[$search,$category,$period]=catalogueFilters(true);$events=fetchCatalogue(true);$total=(int)$pdo->query('SELECT COUNT(*) FROM events')->fetchColumn();pageStart('Event list'); ?>
<p class="label">ADMIN · VIEW RECORDS</p><h1>Events</h1><p><strong><?=$total?></strong> events in total. Showing <?=count($events)?> event(s) matching your filters.</p><?php catalogueForm($search,$category,$period,'admin_events.php'); ?>
<div class="table-scroll"><table><caption>Event directory · View only</caption><thead><tr><th>ID</th><th>Event</th><th>Category</th><th>Venue</th><th>Next / last session</th><th>Date group</th><th>Visibility</th></tr></thead><tbody><?php foreach($events as $e): ?><tr><td><?=h($e['event_id'])?></td><td><?=h($e['event_name'])?></td><td><?=h($e['category'])?></td><td><?=h($e['venue_name'])?></td><td><?=h($e['next_session']??$e['last_session']??'No active sessions')?></td><td><span class="badge"><?=h(eventPeriod($e)==='unscheduled'?'Dates pending':ucfirst(eventPeriod($e)))?></span></td><td><?=h($e['status'])?></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="7">No events match these filters.</td></tr><?php endif; ?></tbody></table></div><p>Past events have no future active sessions. Events with both past and future sessions remain Upcoming.</p><p>To add or edit events, open <a href="admin_manage.php">Manage</a> → Manage events.</p><?php pageEnd(); ?>
